solution.solution.ts:
interface Book { isbn: string; title: string; author: string; year: number; tags?: string[] }
interface Loan { isbn: string; member: string; due: string }

function addBook(books: readonly Book[], book: Book): Book[] {
  if (books.some(b => b.isbn === book.isbn)) throw new Error(`duplicate isbn ${book.isbn}`);
  return [...books, book];
}

function byAuthor(books: readonly Book[]): Record<string, string[]> {
  const sorted = [...books].sort((a, b) => a.year - b.year || a.title.localeCompare(b.title));
  const out: Record<string, string[]> = {};
  for (const book of sorted) {
    if (!out[book.author]) out[book.author] = [];
    out[book.author].push(book.title);
  }
  return out;
}

function overdue(loans: readonly Loan[], books: readonly Book[], today: string): string[] {
  const titles = new Map(books.map(b => [b.isbn, b.title]));
  return loans
    .filter(loan => loan.due < today)
    .sort((a, b) => a.due.localeCompare(b.due) || a.member.localeCompare(b.member))
    .map(loan => `${loan.member}: ${titles.get(loan.isbn) ?? "unknown book"} (due ${loan.due})`);
}

unitTests:
const books = [
  { isbn: "1", title: "Dune", author: "Herbert", year: 1965 },
  { isbn: "2", title: "Children of Dune", author: "Herbert", year: 1976 },
  { isbn: "3", title: "Dune Messiah", author: "Herbert", year: 1969 },
  { isbn: "4", title: "Kindred", author: "Butler", year: 1979, tags: ["classic"] },
];

test("adding books", () => {
  const more = addBook(books, { isbn: "5", title: "Dawn", author: "Butler", year: 1987 });
  checkEq(more.length, 5);
  checkEq(books.length, 4);
  checkThrows(() => addBook(books, { isbn: "1", title: "Copy", author: "X", year: 2000 }));
  try { addBook(books, { isbn: "2", title: "Copy", author: "X", year: 2000 }); }
  catch (e) { checkEq((e as Error).message, "duplicate isbn 2"); }
});

test("titles by author", () => {
  checkEq(byAuthor(books), { Herbert: ["Dune", "Dune Messiah", "Children of Dune"], Butler: ["Kindred"] });
  checkEq(byAuthor([]), {});
});

test("overdue loans", () => {
  const loans = [
    { isbn: "4", member: "zoe", due: "2026-03-01" },
    { isbn: "1", member: "amy", due: "2026-03-01" },
    { isbn: "9", member: "bob", due: "2026-02-10" },
    { isbn: "2", member: "cy", due: "2026-03-05" },
    { isbn: "3", member: "di", due: "2026-03-04" },
  ];
  checkEq(overdue(loans, books, "2026-03-04"), [
    "bob: unknown book (due 2026-02-10)",
    "amy: Dune (due 2026-03-01)",
    "zoe: Kindred (due 2026-03-01)",
  ]);
});

